function useDecrypt(config) {
  const toUnit8Array = (raw) => Uint8Array.from(raw)
  return {
    decrypt: async (password, text) => {
      if (!password) return
      const key = await getCryptoDeriveKey(
        await getKeyMaterial(password),
        toUnit8Array(config.value.salt),
      )
      const ciphertextData = Uint8Array.from(text, (c) => c.charCodeAt(0))
      const decrypted = await window.crypto.subtle.decrypt(
        {
          name: 'AES-CBC',
          iv: toUnit8Array(config.value.iv),
        },
        key,
        ciphertextData,
      )
      return new TextDecoder().decode(decrypted)
    },
  }
}

function getKeyMaterial(password) {
  const enc = new TextEncoder()
  return window.crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, [
    'deriveBits',
    'deriveKey',
  ])
}

function getCryptoDeriveKey(keyMaterial, salt) {
  return window.crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt,
      iterations: 1e5,
      hash: 'SHA-256',
    },
    keyMaterial,
    {
      name: 'AES-CBC',
      length: 256,
    },
    true,
    ['encrypt', 'decrypt'],
  )
}

export {useDecrypt}
